ClaimsPrincipal Who(string id)=>new(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,id),new Claim("AspNet.Identity.SecurityStamp",id+"-stamp"),new Claim(PasskeyAdditionService.SessionClaim,id+"-session")],"Identity.Application"));
async Task Change(Func<ApplicationDbContext,Task> action){await using var db=await factory.CreateDbContextAsync();await action(db);await db.SaveChangesAsync();}
async Task<EventPushDelivery[]> Jobs(string id){await using var db=await factory.CreateDbContextAsync();return await db.Set<EventPushDelivery>().AsNoTracking().Where(x=>x.EventId==id&&x.Kind=="PartStart").ToArrayAsync();}
async Task<string> Event(bool opening=false){clock.Now=initial;var id=await core.SaveEventAsync(Who("admin"),null,new("Private event","","",initial,opening?initial.AddMinutes(-1):null,"","View",[],0));await Change(async db=>{(await db.SessionEvents.SingleAsync(x=>x.Id==id)).ManualPhaseOverride=true;db.TimeParts.Add(new(){Id="talk-"+id,EventId=id,Kind="Transition",Name="Sensitive transition",DurationSeconds=120});});return id;}
async Task Arm(string id,string part,string user="member"){var v=await core.ReadPartStartPreferencesAsync(Who(user),id);var p=v.Parts.Single(x=>x.PartId==part);await core.SavePartStartPreferenceAsync(Who(user),id,new(part,true,p.Version,v.EventVersion));}
async Task RecordNext(string id){clock.Now=clock.Now.AddSeconds(1);var p=await core.ReadProgressAsync(Who("admin"),id);await core.RecordProgressAsync(Who("admin"),id,new(Guid.NewGuid().ToString(),p.RowVersion,p.ProgressVersion,p.NextAction!.PartId,p.NextAction.Point));}
async Task<string> Queued(){var id=await Event();await Arm(id,"talk-"+id);await RecordNext(id);await scheduler.Generate(id);Check((await Jobs(id)).Length==2,"Personal Start creates only opted-in user's two device jobs");return id;}
